package com.shixiaoyu.xiangyueproject.service.Impl;import cn.hutool.core.bean.BeanUtil;import cn.hutool.core.util.StrUtil;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;import com.shixiaoyu.xiangyueproject.entity.dto.PageResultDTO;import com.shixiaoyu.xiangyueproject.entity.dto.SystemConfigDTO;import com.shixiaoyu.xiangyueproject.entity.po.SystemConfig;import com.shixiaoyu.xiangyueproject.entity.vo.PageResultVO;import com.shixiaoyu.xiangyueproject.entity.vo.SystemConfigVO;import com.shixiaoyu.xiangyueproject.exception.BusinessException;import com.shixiaoyu.xiangyueproject.mapper.SystemConfigMapper;import com.shixiaoyu.xiangyueproject.service.SystemConfigService;import com.shixiaoyu.xiangyueproject.utils.SecurityUtil;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.util.List;import java.util.stream.Collectors;/** * 系统配置服务实现 */@Service@RequiredArgsConstructorpublic class SystemConfigServiceImpl extends ServiceImpl<SystemConfigMapper, SystemConfig>        implements SystemConfigService {    private final SystemConfigMapper systemConfigMapper;    /**     * 管理端分页列表     */    @Override    public PageResultVO<SystemConfigVO> list(PageResultDTO pageResultDTO, String keyword) {        SecurityUtil.requireAdmin();        int pageNo = normalizePageNo(pageResultDTO);        int pageSize = normalizePageSize(pageResultDTO);        LambdaQueryWrapper<SystemConfig> wrapper = new LambdaQueryWrapper<SystemConfig>()                .like(StrUtil.isNotBlank(keyword), SystemConfig::getConfigKey, StrUtil.trim(keyword))                .orderByAsc(SystemConfig::getConfigKey);        Page<SystemConfig> page = systemConfigMapper.selectPage(Page.of(pageNo, pageSize), wrapper);        List<SystemConfigVO> voList = page.getRecords().stream()                .map(this::toVo)                .collect(Collectors.toList());        return new PageResultVO<>(page.getTotal(), voList);    }    /**     * 单条详情     */    @Override    public SystemConfigVO detail(String configKey) {        SecurityUtil.requireAdmin();        SystemConfig config = requireConfig(configKey);        return toVo(config);    }    /**     * 新增配置     */    @Override    public void create(SystemConfigDTO dto) {        SecurityUtil.requireAdmin();        String key = normalizeKey(dto.getConfigKey());        if (systemConfigMapper.selectById(key) != null) {            throw new BusinessException("配置键已存在：" + key);        }        SystemConfig po = new SystemConfig(key, dto.getConfigValue().trim());        systemConfigMapper.insert(po);    }    /**     * 更新配置值     */    @Override    public void update(SystemConfigDTO dto) {        SecurityUtil.requireAdmin();        String key = normalizeKey(dto.getConfigKey());        requireConfig(key);        SystemConfig update = new SystemConfig();        update.setConfigKey(key);        update.setConfigValue(dto.getConfigValue().trim());        systemConfigMapper.updateById(update);    }    /**     * 删除配置     */    @Override    public void delete(String configKey) {        SecurityUtil.requireAdmin();        String key = normalizeKey(configKey);        requireConfig(key);        systemConfigMapper.deleteById(key);    }    private SystemConfig requireConfig(String configKey) {        SystemConfig config = systemConfigMapper.selectById(configKey);        if (config == null) {            throw new BusinessException("配置不存在：" + configKey);        }        return config;    }    private String normalizeKey(String configKey) {        if (StrUtil.isBlank(configKey)) {            throw new BusinessException("配置键不能为空");        }        return StrUtil.trim(configKey);    }    private SystemConfigVO toVo(SystemConfig po) {        return BeanUtil.copyProperties(po, SystemConfigVO.class);    }    private int normalizePageNo(PageResultDTO pageResultDTO) {        if (pageResultDTO == null || pageResultDTO.getPageNo() == null || pageResultDTO.getPageNo() < 1) {            return 1;        }        return pageResultDTO.getPageNo();    }    private int normalizePageSize(PageResultDTO pageResultDTO) {        if (pageResultDTO == null || pageResultDTO.getPageSize() == null || pageResultDTO.getPageSize() < 1) {            return 10;        }        return pageResultDTO.getPageSize();    }}